new['version']='R10 - Arbeitsvorschlag zur Diskussion, offene AG-Entscheidungen';new['date']='2026.10.27'
responses_path=folder/'2026.10.27 Raspunsuri proprietar BERGER.json';answers=json.loads(responses_path.read_text(encoding='utf-8')) if responses_path.exists() else {}
mods=[]
def add(id,pages,refs,title,raw,confidence,assessment,proposal,question,status='DESCHIS / propunere neaprobata'):
 mods.append(dict(id=id,pagini_scan=pages,referinte=refs,titlu=title,manuscris=raw,certitudine=confidence,analiza_RO=assessment,propunere_RO=proposal,intrebare_proprietar=question,status=status,raspuns=answers.get(id)))
add('M01',[1],['1(4)','4(1)','4(5)','A2','A6'],'Polierpläne / responsabilul arhitectural','Wer zeichnet die Polierpläne? ... gibt es ... schon [ultimele cuvinte parțial neclare]','medie','Nota cere un responsabil pentru planurile arhitecturale de execuție; acestea trebuie delimitate de planurile statice BERGER.','Numim responsabilul în anexe, păstrăm planurile statice și interfețele la BERGER; nu introducem Baumanagement/Planung generală.','Cine face Polierpläne și ce planuri există deja?')
add('M02',[1],['1(4)','8(5)','A6'],'Bauführer','Wer ist der Bauführer?','ridicată','Bauführer este o funcție distinctă de proiectant și PI. Nu deducem o numire din simpla semnare a contractului de statică.','Persoana/firma și notificarea către autoritate se completează separat înainte de începere; PI trebuie să îndeplinească incompatibilitățile legale.','Cine este Bauführer? Dacă nu e ales, lăsăm câmpul deschis. [L1,L4]')
add('M03',[1],['1(4)','9(1)','9(2)','A3'],'Începerea efectivă','Wann ist der tatsächliche Baubeginn?','ridicată','Data unei întâlniri, contractul sau numirea PI nu sunt începutul execuției.','Păstrăm T0 pentru proiectare, B0 real pentru șantier și 18 luni de la B0; data estimată și cea efectivă se înregistrează separat.','Care este data estimată a începerii și există o dată de proiectare T0 convenită?')
add('M04',[1,4],['2(2)','4(4)','4(5)','A2'],'Planwechsel / Einreichplaner','... kein Planwechsel [lectură parțial nesigură]; Wer kommt? Gibt es schon einen Entwurf?','medie','Nu tratăm ca fapt existența unui Planwechsel. Autorizația din 2023 și orice proiect ulterior trebuie identificate exact.','Păstrăm o modificare structurală convenită inclusă; ea devine o livrare concretă numai dacă este cerută. Nominalizăm Einreichplaner.','Există un Planwechsel pregătit, depus ori aprobat? Cine este Einreichplaner?')
add('M05',[3],['3(4)','A1'],'Baugrubensicherung / Verbau','wird es nicht geben [la delimitarea Verbau]','medie-ridicată','Nota nu trebuie transformată într-o renunțare la sprijinirile statice ale clădirii sau la avertizarea asupra riscurilor.','Menținem excluderea proiectării Verbau, deja cerută de proprietar, și păstrăm subzidirile/sprijinirile structurii proprii și datele de sarcină.','Doar dacă soluția tehnică se schimbă: ce prestator preia eventuala asigurare a excavației?',status='CLARIFICARE / excluderea Verbau se păstrează')
add('M06',[3,4],['4(1)','4(2)','4(3)','A1','A3','A6'],'Detalii de oțel și planuri de atelier','... KEINE WERK[STATT]PLÄNE; ... mit tatsächlicher Stahlbaufirma abzustimmen; knapp','medie-ridicată','Este corect să distingem planurile de fabricație ale executantului de calculele, forțele și detaliile structurale ale BERGER. Nu transferăm automat toate nodurile la un executant încă neales.','Coordonare cu firma efectivă de oțel; BERGER păstrează dimensionarea și verificarea compatibilității. Propunem 5 zile lucrătoare pentru verificarea uzuală a planurilor de atelier.','Acceptăm 5 zile sau păstrăm 2 / cerem un calendar concret? Cine este firma de oțel?')
add('M07',[5],['5(1)','5(2)','A6'],'Persoana PI','wird DI [Zell?] sein','scăzută pentru nume; ridicată pentru sens','Numele nu poate fi stabilit sigur din manuscris. Titlul DI singur nu dovedește calitatea necesară pentru PI.','Nu introducem un nume presupus. Cerem identitatea exactă, calitatea profesională, independența și dovada notificării/luării la cunoștință.','A fost ales PI? Numele, angajatorul, contractarea și plata? [L1,L4]')
add('M08',[5,8],['5(3)','7(1)','7(4)','7(5)','A3','A4','A6'],'PI: program, număr de controale, preț','Was ist ein Beschauplan? Der Prüfingenieur entscheidet ... was er abnimmt [mijloc parțial neclar]; wie viele?','medie','PI stabilește tehnic controalele necesare; un număr comercial de vizite nu poate înlocui verificările obligatorii. Dar onorariul și întinderea trebuie acceptate expres.','Definim programul de controale și păstrăm toate controalele PI ale proiectului în propunerea de 10.000 EUR, separat de cele 8 vizite statice; niciun supliment sau plafon nu este prezumat acceptat.','S-a convenit astăzi un plafon PI ori un tarif separat? Dacă nu, cerem confirmare explicită a pachetului. [L1]')
add('M09',[5,6],['5(4)','5(8)','A1','A6'],'Prüfprogramm / zusätzliche Prüfstatik','Was stellt das dar? GEHT NICHT; Was soll das genau sein?','ridicată','R09 amestecă funcția PI, controlul intern al calculelor și o eventuală verificare statică separată. Nu orice PI înseamnă recalcularea independentă integrală a proiectului.','Separăm responsabilitatea proiectantului și controlul propriu de controalele legale PI. O verificare statică suplimentară distinctă se identifică concret înainte de contractare și de alocarea costului.','Există o Prüfstatik separată impusă de autorizație/autoritate? A fost discutat cine o face și în ce preț?')
add('M10',[5,6],['5(6)','5(7)','A6'],'Certificarea finală ZT','DI [Zell?] [lângă funcția de finalizare]','scăzută pentru nume','Calitatea de expert judiciar pentru PI nu echivalează singură cu competența ZT cerută pentru confirmarea integrală de finalizare.','Păstrăm cerința de ZT independent și documentele proprii/terțe delimitate; numele și includerea comercială se confirmă înainte de semnare.','Este aceeași persoană pentru PI și certificarea ZT? Ce servicii și costuri au fost convenite? [L2]')
add('M11',[1,6],['2(1)','3(6)','5(7)','6(1)','6(2)','6(3)','6(4)','6(5)','6(6)','6(7)','8(2)','9(2)','9(3)','9(7)','10(6)','11(1)','A1','A3','A4','A6'],'Bauwerksbuch: excludere cerută de BERGER','nicht inkludiert! [de două ori]','ridicată','Este o divergență comercială reală. Obligația legală a proprietarului nu dovedește că BERGER a ofertat cartea clădirii în cei 45.000 EUR.','Până la decizia proprietarului păstrăm cererea noastră pentru existent + intervenții noi, prima verificare și înregistrare. Nu adăugăm preț și nu considerăm serviciul acceptat de BERGER.','Îl cerem în 45.000 EUR, cerem o ofertă separată fără aprobare sau alegem alt prestator? [L3,L5]')
add('M12',[1,8],['2(1)','7(1)','7(3)','A3','A4'],'Definirea vizitei fizice / Betreuung','Notă scurtă la Betreuung [ilizibilă sigur]; Was ist das? [digitale Besprechung / administrative Bestellung]','scăzută pentru prima notă; ridicată pentru întrebare','Textul trebuie să spună simplu ce consumă o vizită și ce rămâne coordonare uzuală.','Înlocuim formularea ambiguă despre administrative Bestellung cu telefon/videoconferință și diferențiem coordonarea de prezența efectivă pe șantier. Rămân 8 vizite, T0 inclus dacă există asistență statică efectivă.','Dacă BERGER atribuie alt sens notei la Betreuung, îl rugăm să îl confirme; nu deducem un nou tarif.',status='CLARIFICARE / fără schimbarea numărului sau prețului')
add('M13',[9],['7(6)'],'Răspunsuri tehnice RFI','drei [corectează zwei]','ridicată','Corecția manuscrisă este concretă: trei zile în loc de două. Urgențele și verificările înainte de acoperirea lucrărilor trebuie păstrate.','Propunem 3 zile lucrătoare pentru răspunsurile uzuale; avertizarea de siguranță rămâne imediată, iar un răspuns complex primește un termen justificat.','Acceptăm termenul de 3 zile?')
add('M14',[5,10],['5(4)','8(6)','A1','A6'],'Materiale, probe și Würfelbefunde','Das Material gibt es ... [final neclar]; sublinierea verificărilor de materiale','medie','La semnare materialele noi și rapoartele probelor viitoare pot să nu existe încă. Aceasta nu elimină verificarea documentelor când apar.','Certificările și probele se solicită conform fazei de șantier, înainte de încorporare/acoperire. Laboratoarele noi se comandă distinct; rapoartele nu sunt inventate sau declarate pozitive anticipat.','Dacă există deja un laborator sau un pachet de încercări contractat, cine este și ce acoperă?',status='CLARIFICARE TEHNICĂ / fără aprobare de costuri')
add('M15',[11],['9(3)','9(8)'],'Status săptămânal și registre','mit Form? per E-Mail; Mehraufwand; semn de întrebare','medie-ridicată','O listă simplă de decizii și documente este utilă; nu este necesar să impunem o aplicație sau formulare speciale neconvenite.','Propunem email săptămânal scurt în perioadele active și o listă comună simplă; rapoartele PI și documentele tehnice rămân obligatorii.','Email scurt + listă simplă, forma inițială sau status numai pe etape?')
add('M16',[12],['10(1)','10(6)','10(7)','A1','A6'],'Formate IFC, DWG/DXF și fișiere native','haben wir das?; keine ... [fragment neclar]; händische Liste!; geht auch!','medie/scăzută pentru fragmente','Nu se poate deduce din notă existența unui model IFC sau a unei obligații acceptate de a crea un BIM nou. Predarea editabilă și calculele verificabile rămân importante.','Varianta de lucru A: PDF + DWG/DXF editabile, calcule complete și fișiere de proiect disponibile; IFC dacă există. Varianta B: păstrarea integrală a cerinței R09. Alegerea proprietarului este încă deschisă.','IFC/fișiere native obligatorii, doar dacă există, sau decizie după confirmarea formatelor și a eventualelor costuri?')
add('M17',[12],['10(2)','A1'],'Planuri, liste și revizii','acoladă și semn de întrebare la §10(2)','ridicată pentru marcaj; sens nespecificat','Nu există o contrapropunere textuală precisă; păstrăm un standard clar de predare, fără să atribuim lui BERGER acceptarea unei soluții.','Precizăm planuri cotate, scări/unități, număr de plan și revizie; listele se pot preda în formatul electronic utilizat, lizibil și reutilizabil.','Ce formate poate furniza efectiv BERGER? Orice renunțare la editabilitate necesită decizia proprietarului.')
add('M18',[13],['11(1)','12(1)','A4'],'Calendar de plată cu valori','ein Zahlungsplan kann mit Bauablauf vereinbart werden [lectură de sens]','medie-ridicată','Observația este compatibilă cu solicitarea anterioară a proprietarului. Nu este un acord asupra procentelor, avansurilor ori scadențelor.','Introducem o anexă agreată înainte de semnare cu livrări, date și valori. Păstrăm cele patru poziții și totalul, 14 zile fără reținere și fără penalitate.','BERGER să propună calendarul cu sume și livrabile; proprietarul confirmă înainte de semnare.',status='PROPUNERE / calendarul valoric încă lipsește')
add('M19',[16],['14(3)','14(4)','A6'],'Dovada asigurării existente','wird bereitgestellt','ridicată','Este promisiunea de a furniza dovada, nu dovada însăși. Polița istorică nu dovedește automat acoperirea actuală.','Păstrăm numai dovada actuală a acoperirii existente și funcțiilor asumate, fără o nouă limită minimă contractuală.','Nu cere o decizie comercială nouă; BERGER trebuie să transmită documentul actual.',status='DE FURNIZAT / fără înăsprirea asigurării')
add('M20',[1,3,4,5,6,8,9,10,11,12,13,16],['A1','A2','A3','A4','A6'],'Coerența anexelor','Anexele 19–29 nu au fost returnate în scan','fapt verificat','Scanul nu dovedește acceptarea anexelor nemarcate. Orice modificare a contractului trebuie reflectată și acolo.','Actualizăm consecvent referințele la PI, vizite, verificări, formate și calendarul de facturare; prețurile originale rămân neschimbate.','Se închid anexele numai după răspunsurile proprietarului și confirmarea scrisă BERGER.',status='CORELARE NECESARĂ / nu este acceptare a anexelor')
add('M21',[7],['6(4)'],'Trimiteri legale aplicabile','Fără notă manuscrisă; verificare juridică de coerență','verificare documentară','Textul actual al §128a alin.(4) pct.7 face trimitere la §118c alin.(2) și (7). Trebuie verificată versiunea aplicabilă proiectului autorizat în 2023.','Înlocuim trimiterea rigidă la vechiul §118 cu o referire la obligația aplicabilă concret și păstrăm analiza tranzitorie din §2.','Specialistul de proiect confirmă regimul aplicabil; nu cerem automat modernizarea întregului proiect din cauza unei modificări legislative.',status='CORECȚIE DE REFERINȚĂ / aplicabilitatea se verifică')

def para(s,p):return new['sections'][s-1]['paragraphs'][p-1]
def setp(s,p,t):new['sections'][s-1]['paragraphs'][p-1]=t
new['sections'][0]['paragraphs'].append('Die architektonische Ausführungs- und Polierplanung wird durch die in Anlage 6 bezeichnete Fachperson [vor Unterzeichnung zu ergänzen] erbracht; ihre Abgrenzung zur statischen Ausführungsplanung des AN ist in Anlage 2 festzuhalten. Bauführer und ausführende Unternehmen werden gesondert benannt. Der geplante bauliche Beginn B0 wird vor Unterzeichnung dokumentiert und vom später festzustellenden tatsächlichen B0 getrennt dokumentiert. Eine noch offene Namens- oder Datumsangabe gilt nicht als Bestellung oder als bereits eingetretener Baubeginn.')
setp(2,1,para(2,1).replace('Ausführungsunterlagen, Betreuung, Prüfingenieur','Ausführungsunterlagen, statische Betreuung nach § 7, Prüfingenieur'))
setp(2,2,para(2,2)+' Ob ein Planwechsel bereits vorliegt, beantragt oder erst vorgesehen ist, wird in Anlage 2 mit Datei, Index, Datum und Verfahrensstand ausdrücklich festgehalten; sein Vorliegen wird durch diese Klausel nicht behauptet.')
setp(4,1,para(4,1)+' Allgemeine architektonische Polierpläne sind von diesen statischen Ausführungsunterlagen zu unterscheiden und werden durch die in Anlage 6 bezeichnete Fachperson bereitgestellt; die rechtzeitige statische Schnittstellenabstimmung bleibt Aufgabe des AN.')
setp(4,2,'Der AN verantwortet die tragwerksrelevante Bemessung und legt die maßgeblichen Kräfte, Abmessungen, Werkstoffe, Anschluss- und Verankerungsanforderungen nachvollziehbar fest. Herstellungsabhängige Anschlussdetails werden mit dem tatsächlich beauftragten Stahl- oder Holzbauunternehmen abgestimmt; dessen Werkstattplanung nach Abs. 3 bleibt von den eigenen statischen Planungs- und Prüfpflichten des AN getrennt. Die für Bestellung und Herstellung erforderlichen statischen Angaben sind mit dem betroffenen Lieferpaket D2, D3, D4 oder D5 rechtzeitig bereitzustellen. Eine bloße Verweisung auf einen noch unbekannten Hersteller ersetzt keine bereits fällige eigene Bemessung. Vor Herstellung werden die prüfpflichtigen Anschluss- und Werkstattunterlagen auf Übereinstimmung mit der Statik kontrolliert; noch offene Angaben und Freigabegrenzen werden ausdrücklich bezeichnet.')
setp(4,3,para(4,3).replace('binnen zwei Werktagen','binnen fünf Werktagen'))
setp(4,4,para(4,4)+' Der enthaltene Planwechsel wird nur auf konkrete, dokumentierte Anforderung der AG ausgearbeitet; ein bereits vorliegender oder eingereichter Planwechsel wird damit nicht unterstellt.')
setp(4,5,para(4,5)+' Die zuständige Person sowie vorhandene Entwürfe und der tatsächlich bewilligte Architekturstand werden in Anlagen 2 und 6 bezeichnet; noch fehlende Unterlagen sind mit Termin und Verantwortlichem anzufordern.')
setp(5,1,para(5,1)+' Identität, aktuelle einschlägige Befugnis, Unabhängigkeit und vertragliche Einbindung der tatsächlich tätigen Person sind vor Unterzeichnung beziehungsweise jedenfalls vor der erforderlichen Bestellung nachzuweisen; die Funktionsübernahme setzt die eindeutige Benennung und den Nachweis der erforderlichen Befugnis voraus.')
setp(5,3,'Der benannte Prüfingenieur legt auf Grundlage der Bewilligung, des Tragwerks, des tatsächlichen Bauablaufs und der gesetzlichen Aufgaben die notwendigen Prüfungen, Beschauen und Haltepunkte fest und dokumentiert sie in einem vor B0 abgestimmten Prüf- und Beschauplan. Dieser bezeichnet Bauteil, Prüfgegenstand, Anlass oder Bauphase, erforderlichen Vorlauf und Befund. Die für das vereinbarte Vorhaben erforderlichen PI-Leistungen einschließlich der hierfür notwendigen Anwesenheiten werden im Vertragsvorschlag der eigenen Pauschale von EUR 10.000,00 zugeordnet; ihr Umfang und diese Preiszuordnung sind vor Unterzeichnung ausdrücklich zu bestätigen. Die Zahl der statischen Betreuungsbesuche nach § 7 bildet keinen Ersatz oder Höchstwert gesetzlich erforderlicher PI-Kontrollen. Eine reine PI-Anwesenheit wird nicht zusätzlich als statische Betreuung verrechnet. Bei gemeinsamem tatsächlichem PI- und Betreuungsinhalt wird derselbe Termin höchstens einmal als Betreuungsbesuch erfasst; eine zweite Wegvergütung entfällt. Keine notwendige Prüfung wird ausgelassen oder ohne tatsächliche Durchführung bestätigt. Echte Änderungen des vereinbarten Vorhabens werden nach § 11 abgegrenzt.')
setp(5,4,'Der AN bleibt für die Richtigkeit und vollständige Dokumentation seiner eigenen Tragwerksplanung einschließlich fachgerechter interner Qualitätssicherung verantwortlich. Davon zu unterscheiden sind die gesetzlichen PI-Überprüfungen der Bauausführung und eine gegebenenfalls zusätzlich angeordnete eigenständige Prüfstatik. Der Plan/Statik-Abgleich, die erforderliche Beurteilung von Hersteller- und Werkstattunterlagen sowie die Prüfung der im vereinbarten Tätigkeitsbereich benötigten Materialnachweise werden konkret im Prüf- und Schnittstellenplan zugeordnet. Prüfzeugnisse und Würfelbefunde werden nach tatsächlichem Baufortschritt rechtzeitig angefordert und auf Plausibilität und Verwendbarkeit geprüft; eine eigene Laborleistung wird dadurch nicht ohne gesonderte Vereinbarung beauftragt. Gesetzliche Befugnis-, Unabhängigkeits-, Kontroll- und Warnpflichten werden nicht eingeschränkt.')
setp(5,6,para(5,6)+' Die tatsächlich ausstellende ZT-Person, ihre Zuständigkeit und die Preiszuordnung werden in Anlage 6 ausdrücklich bestätigt; die organisatorische und fachliche Zuordnung wird eindeutig dokumentiert.')
setp(5,8,'Vor Unterzeichnung wird anhand der Bewilligung und der fachlich erkennbaren Anforderungen festgehalten, ob neben der eigenen Qualitätssicherung und den gesetzlichen PI-Leistungen eine zusätzliche eigenständige Prüfstatik benötigt wird. Prüfgegenstand, befugte Person, Verantwortlichkeit und Preiszuordnung werden in Anlage 6 konkret bezeichnet. Eine offene Bezeichnung begründet weder die Bestellung einer unbestimmten Drittleistung noch eine automatische Kostenübernahme der AG. Für die bereits geschuldeten eigenen Planungs-, Prüf- und Warnpflichten entsteht kein Zusatzhonorar. Eine später notwendige echte Zusatzleistung wird nach § 11 behandelt; gesetzliche Sicherheits- und Behördenpflichten bleiben gewahrt.')
setp(6,4,'Die im konkreten Fall nach § 128a Abs. 4 Z 7 BO für Wien erforderliche Dokumentation einschlägiger Maßnahmen und Änderungen wird in der auf das Vorhaben jeweils anwendbaren Fassung integriert. Die maßgeblichen Vorschriften und allfälligen Übergangsregeln werden nach § 2 dokumentiert; aus dieser Verweisung folgt kein pauschaler rückwirkender Umbauauftrag. Soweit einschlägig liefern Energie- und Haustechnikfachplaner unter Mitwirkung der AG die fachfremden Nachweise. Der AN fordert sie konkret an, ordnet sie zu und dokumentiert Fehlendes. Eigene Energiesystemplanung, physische Bauausführung und die Reparatur historischer Gebäudeschäden sind dadurch nicht beauftragt.')
setp(7,1,para(7,1).replace('Eine rein digitale Besprechung oder administrative Bestellung zählt nicht als physischer Besuch. PI-Beschauen werden gesondert nach § 5, ohne zahlenmäßige Besuchsgrenze, erfüllt.','Ein ausschließliches Telefonat, eine Videokonferenz oder die rein administrative Abwicklung eines Auftrags ist kein physischer Baustellenbesuch. Die notwendige übliche fachliche Fernkoordination ist enthalten. Umfang und Preiszuordnung der PI-Beschauen richten sich gesondert nach § 5; die Zahl der statischen Besuche begrenzt nicht die gesetzlichen PI-Pflichten.'))
setp(7,3,para(7,3).replace('in einem zugänglichen Register','in einer gemeinsamen zugänglichen Termin- und Befundliste'))
setp(7,6,para(7,6).replace('binnen zwei Werktagen','binnen drei Werktagen'))
setp(8,6,'Die im Paket enthaltene Materialkontrolle bezeichnet die fachlich erforderliche Prüfung der im PI-/Tragwerksbereich benötigten Zertifikate, Herstellerunterlagen, Prüfberichte und Würfelbefunde. Für erst künftig einzubauende Materialien müssen diese Nachweise nicht schon bei Vertragsschluss existieren; sie werden nach einem dokumentierten Anforderungsplan rechtzeitig vor der jeweiligen Verwendung, Freigabe oder erforderlichen Überprüfung bereitgestellt. Fehlende, negative oder widersprüchliche Nachweise werden ausdrücklich vermerkt; eine noch nicht erfolgte Prüfung gilt nicht als positiv. Neue physische Laborprüfungen und deren Kosten werden als Drittleistung konkret abgegrenzt und nach § 11 beauftragt. Die Prüfung der tatsächlich vorgelegten Befunde sowie gesetzliche Kontroll- und Warnpflichten bleiben davon unberührt.')
setp(9,3,para(9,3).replace('Der AN berichtet wöchentlich kurz über erreichte Lieferstände, offene Entscheidungen, Risiken und nächste Schritte.','Die laufende kurze Statusinformation erfolgt nach Abs. 8; ein zweiter gleichlautender Wochenbericht wird nicht verlangt.'))
setp(9,8,'Während aktiver Planungs- oder Bauleistungen übermittelt der AN wöchentlich eine kurze E-Mail über erreichte Lieferstände, offene Entscheidungen, Risiken und nächste Schritte. Eine gemeinsam zugängliche einfache Liste hält die maßgeblichen Planrevisionen, Entscheidungen, Freigaben, Mängel, Verantwortlichen und Termine aktuell; zusätzliche Spezialsoftware oder besondere Berichtsformulare werden nicht verlangt. Gesetzlich erforderliche Befunde und fachliche Freigaben werden dadurch nicht ersetzt. Diese normale fachliche Koordination ist im Paket enthalten und keine allgemeine kaufmännische Projektsteuerung.')
setp(10,1,'Jede Lieferung umfasst unterfertigte, behördentaugliche PDF-Unterlagen sowie bearbeitbare DWG-Dateien und einen technisch geeigneten DXF-Austausch der beauftragten Tragwerksplanung. Verwendete Software und Version werden in der Übergabeliste bezeichnet. Vollständige nachvollziehbare Berechnungen einschließlich Eingaben, Lastannahmen, Systemen und Ergebnissen sowie Bewehrungs-, Biege-, Material-, Mengen- und Stücklisten werden in lesbarer und soweit vorhanden weiterverwendbarer elektronischer Form mitgeliefert. Vorhandene projektbezogene Berechnungs- und Modelldateien werden mitübergeben, soweit rechtlich und technisch übertragbar; nicht übertragbare Lizenzen oder geschützte Bibliotheken werden nicht geschuldet. Ein vorhandenes IFC-Modell wird im verwendeten Austauschformat übergeben. Ob darüber hinaus ein neues IFC-Modell oder ein bestimmtes natives Datenformat verpflichtend zu erstellen ist, ist vor Unterzeichnung ausdrücklich in Anlage 1 zu entscheiden; diese noch offene Wahl begründet weder dessen Abbestellung noch einen Zusatzpreis.')
setp(10,2,'Pläne sind maßstäblich, vollständig lesbar und ausreichend bemaßt; Einheiten, Plannummer, Datum, Index und Änderungsstand sind eindeutig. Führungspläne werden im Regelfall für Ausdruck 1:50 und Details im fachlich geeigneten Maßstab erstellt. Die vereinbarten bearbeitbaren CAD-Dateien erhalten soweit technisch vorhanden nachvollziehbare Bauteil- oder Gewerklayer und Positionsangaben. Zu jeder maßgeblichen Revision werden PDF, die vereinbarte CAD-Fassung und eine aktualisierte einfache Planliste übermittelt. Listen können im verwendeten elektronischen Tabellenformat beziehungsweise als geeigneter weiterverwendbarer Export bereitgestellt werden; eine bloße nicht nachvollziehbare handschriftliche Liste ersetzt keine erforderliche lesbare und überprüfbare Dokumentation.')
setp(10,6,para(10,6).replace('Quellen/Modelle','die nach Abs. 1 vereinbarten Quellen-/Modelldateien'))
setp(10,7,para(10,7).replace('ohne native und bearbeitbare Unterlagen zu ersetzen','ohne die nach Abs. 1 vereinbarten bearbeitbaren Unterlagen zu ersetzen'))
setp(11,1,para(11,1)+' Vor Unterzeichnung wird in Anlage 4 ein zum Bauablauf passender beiderseits bestätigter Leistungs- und Rechnungsplan mit konkreten Liefergegenständen, Daten, Nettobeträgen, Umsatzsteuer und Anrechnung früherer Teilzahlungen ergänzt. Die vier ursprünglichen Honorarpositionen bleiben unverändert. Eine pauschale prozentuale Vorauszahlung ohne den vereinbarten Leistungsbezug wird dadurch nicht eingeführt; noch leere Betrags- oder Datumsfelder gelten nicht als vereinbarte Tranche.')

# Consequential annex changes; all original fee/option/hourly-rate rows stay intact.
for a in new['annexes']:
 if a['number']==1:
  a['paragraphs'][1]+=' Herstellungsabhängige Details werden mit dem tatsächlich beauftragten Stahl-/Holzbauunternehmen abgestimmt; die eigene Bemessungs- und Prüfverantwortung des AN bleibt erhalten.'
  a['paragraphs'].append('Vor Unterzeichnung ausdrücklich zu entscheiden: IFC-Neuerstellung und native Datenformate nach § 10 Abs. 1. Die Variante im Vergleichsdokument ist eine offene Arbeitsfassung; keine stillschweigende Abbestellung oder zusätzliche Vergütung. Bauwerksbuch und endgültige PI-/ZT-Preiszuordnung sind nach §§ 5-6 ausdrücklich zu bestätigen.')
  for t in a['tables']:
   for row in t['rows']:
    for i,v in enumerate(row):row[i]=v.replace('Quellen/Modelle','die nach § 10 vereinbarten Quellen-/Modelldateien')
 if a['number']==2:
  a['tables'][0]['rows'] += [['Architektonische Polierplanung / Einreichplaner','Verantwortliche Fachperson, vorhandene Entwürfe und Schnittstelle zur statischen Planung vor Unterzeichnung bestätigen','________________'],['Planwechsel','Vorhanden / geplant / nicht vorhanden; Verfahren, Dateiname, Index und tatsächlicher Status ausdrücklich bestätigen','________________']]
 if a['number']==3:
  a['paragraphs']=[s.replace('binnen zwei Werktagen','binnen fünf Werktagen') for s in a['paragraphs']]
  a['paragraphs'].append('Beschauplan bedeutet einen vom benannten PI fachlich festgelegten und mit dem Bauablauf abgestimmten Plan erforderlicher Kontrollen, Haltepunkte, Vorläufe und Befunde. Eine Betreuungszahl begrenzt keine gesetzlich erforderliche PI-Prüfung. Die PI-Preiszuordnung bleibt vor Unterzeichnung ausdrücklich zu bestätigen. Für übliche technische RFI werden drei Werktage nach § 7 Abs. 6 vorgeschlagen.')
 if a['number']==4:
  a['paragraphs']=[s.replace('Die vollständigen PI-Leistungen einschließlich der erforderlichen PI-Beschauen sind in der eigenen Pauschale von EUR 10.000,00 ohne numerische Besuchsgrenze enthalten.','Die für das vereinbarte Vorhaben erforderlichen PI-Leistungen und Anwesenheiten werden der eigenen Pauschale von EUR 10.000,00 zugeordnet; Umfang, Prüfplan und Preiszuordnung sind vor Unterzeichnung nach § 5 Abs. 3 ausdrücklich zu bestätigen. Die acht statischen Besuche begrenzen die gesetzlichen PI-Pflichten nicht.') for s in a['paragraphs']]
  a['paragraphs'].append('Vor Unterzeichnung ist der konkrete Leistungs- und Rechnungsplan gemäß § 11 Abs. 1 beiderseits zu ergänzen: Liefergegenstand, Datum, zugeordnete Honorarposition, Nettobetrag, USt und Bruttobetrag sowie Anrechnung früherer Teilzahlungen. Keine bislang nicht abgestimmten Prozenttranchen; die Tabellen der ursprünglichen Honorare und beauftragungsabhängigen Optionen bleiben unverändert. Die abgelehnte Bauwerksbuch-Inklusion und die endgültige PI-/ZT-Zuordnung sind offene Punkte, keine akzeptierten Zusatzbeträge.')
 if a['number']==6:
  a['tables'][0]['rows'] += [['Architektonische Polierplanung / Einreichplaner / Bauführer','Name, Firma, Befugnis, Zuständigkeit und Bestellstatus getrennt bestätigen: ________________'],['PI / ZT: Namensklärung','Vollständigen Namen, aktuelle Befugnis, Unabhängigkeit und Preiszuordnung bestätigen: ________________'],['Offene AG-Entscheidungen','Bauwerksbuch, zusätzliche Prüfstatik, Datenformate, Reaktionsfristen und Kurzberichte entsprechend dem Entscheidungsregister ausdrücklich schließen: ________________']]
  for row in a['tables'][1]['rows']:
   if row[0]=='Werkstatt / Material':row[1]=row[1].replace('binnen zwei Werktagen','binnen fünf Werktagen')+' RFI-Vorschlag drei Werktage; Befunde neuer Materialien nach tatsächlichem Baufortschritt.'
   if row[0]=='PI / ZT / Bauwerksbuch':row[1]+=' Die kommerzielle Einbeziehung des Bauwerksbuchs und die konkrete PI-/ZT-Zuordnung sind noch offen; keine Annahme aus dem unmarkierten Annex.'
   if row[0]=='Physische Termine':row[1]=row[1].replace('umfasst erforderliche PI-Beschauen ohne numerische Besuchsgrenze','umfasst die nach § 5 erforderlichen PI-Leistungen und Anwesenheiten; Umfang und Preiszuordnung sind vor Unterzeichnung ausdrücklich zu bestätigen')
   if row[0]=='Nutzungsrechte / Beendigung':row[1]=row[1].replace('native Unterlagen','die nach § 10 Abs. 1 vereinbarten Datenformate')

